import { Box, Button, Card, CardContent, Container, Stack, Typography } from "@mui/material";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import { mediaUrl } from "../services/api";
import type { HomeCourses } from "../types/home";

export default function BestCourses({ data }: { data?: HomeCourses | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 10 } }}>
      <Container maxWidth="lg">
        <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 36 }, fontWeight: 600, mb: 1 }}>
          {data.highlight ? (
            <>
              <Box component="span" sx={{ color: "#759ae1" }}>
                {data.highlight}
              </Box>{" "}
              {data.title}
            </>
          ) : (
            data.title
          )}
        </Typography>
        <Typography sx={{ color: "#5a6473", mb: 5 }}>{data.description}</Typography>
        <Stack direction="row" flexWrap="wrap" useFlexGap spacing={3} justifyContent="center">
          {(data.items || []).map((course) => (
            <Card
              key={course.id || course.title}
              elevation={0}
              sx={{
                width: { xs: "100%", sm: 320 },
                border: "1px solid #e6eaf2",
                borderRadius: "16px",
              }}
            >
              {mediaUrl(course.image) ? (
                <Box
                  component="img"
                  src={mediaUrl(course.image)}
                  alt={course.title}
                  sx={{ width: "100%", height: 177, objectFit: "contain", p: 2 }}
                />
              ) : null}
              <CardContent>
                <Typography sx={{ color: "#17224d", fontWeight: 700, fontSize: 20, mb: 1 }}>
                  {course.title}
                </Typography>
                <Typography sx={{ color: "#5a6473", mb: 2 }}>{course.description}</Typography>
                <Box component="ul" sx={{ pl: 2.5, mb: 2, color: "#5a6473" }}>
                  {(course.features || []).map((item) => (
                    <Typography key={item.id || item.text} component="li" sx={{ mb: 0.5 }}>
                      {item.text}
                    </Typography>
                  ))}
                </Box>
                {course.exploreUrl ? (
                  <Button href={course.exploreUrl} endIcon={<ArrowForwardIcon />} sx={{ color: "#759ae1", px: 0 }}>
                    Explore Course
                  </Button>
                ) : null}
              </CardContent>
            </Card>
          ))}
        </Stack>
      </Container>
    </Box>
  );
}
